WITH enriched AS (SELECT *, FIRST_VALUE(temp_c, TRUE) OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_temp_c, AVG(status_bits) OVER (PARTITION BY TO_DATE(reading_ts), device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) status_bits_avg_2h, FIRST_VALUE(humidity, TRUE) OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_humidity FROM device_readings WHERE device_code <> 'DV-02') SELECT device_code, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, PERCENTILE_APPROX(status_bits, 0.9) AS status_bits_p90, APPROX_PERCENTILE(pressure, ARRAY(0.25, 0.5, 0.75)) AS pressure_quartiles FROM enriched GROUP BY 1 ORDER BY status_bits_p90
